<?php require_once __DIR__.'/helpers.php'; \App\Manor\Language::apply(); ?>
<!doctype html><html lang="<?=me(\App\Engine\Locale::getLocale())?>" dir="<?=me(\App\Engine\Locale::direction())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=me($settings['seo_title'])?></title><meta name="description" content="<?=me($settings['seo_description'])?>"><?php $canonicalPath=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);if(!empty($settings['public_url'])&&($canonicalPath==='/'||str_starts_with($canonicalPath,'/page/'))):?><link rel="canonical" href="<?=me(rtrim($settings['public_url'],'/').$canonicalPath)?>"><?php endif?><link rel="stylesheet" href="/manor/style.css"><link rel="icon" href="<?=me($settings['favicon_url']?:'/manor/favicon.svg')?>"></head><body class="manor"><a class="skip" href="#main"><?=me(__('manor.skip_to_content'))?></a><header><a class="brand" href="/"> <?php if(!empty($settings['logo_url'])):?><img class="site-logo" src="<?=me($settings['logo_url'])?>" alt="<?=me($settings['website_name'])?>"><?php else:?><?=me($settings['website_name'])?><?php endif?></a><nav aria-label="<?=me(__('manor.main_navigation'))?>"><?php foreach($settings['navigation'] as $entry):$label=$entry['label'];$url=$entry['url'];if(str_contains($url,'#venues')&&!$settings['flags']['venues'])continue;if(str_contains($url,'#contact')&&!$settings['flags']['contact'])continue;?><a href="<?=me($url)?>"><?=me($label)?></a><?php endforeach?><?php if($settings['flags']['enquiries']):?><a class="button" href="/manor/enquire"><?=me($settings['cta'])?></a><?php endif?></nav><?php if(count($settings['languages'])>1):?><div class="language-switch"><a lang="en" href="<?=me(\App\Manor\Language::link('en'))?>">EN</a><?php if(in_array('ar',$settings['languages'],true)):?><a lang="ar" href="<?=me(\App\Manor\Language::link('ar'))?>">العربية</a><?php endif?></div><?php endif?></header><?php if(!empty($settings['preview'])||!empty($settings['publication_draft'])):?><div class="publication-banner"><?=me(__('manor.draft_publication_notice'))?></div><?php endif?><main id="main">
